Convert SQL to PySpark:
```sql
SELECT * FROM (
    SELECT segment, country, credit_limit FROM customers
) PIVOT (
    SUM(credit_limit) FOR country IN ('TH', 'US', 'SG')
);
```

Convert SQL to PySpark:
```sql
select budget_bucket, dept_name, berlin_count
from (
    select case when budget >= 4436000 then 'high' when budget >= 872000 then 'mid' else 'low' end as budget_bucket, dept_name, count(case when location = 'Berlin' then 1 end) as berlin_count
    from departments
    group by case when budget >= 4436000 then 'high' when budget >= 872000 then 'mid' else 'low' end, dept_name
) as s
where berlin_count > 9;
```

Convert SQL to PySpark:
```sql
select *
from (
    select *, row_number() over (partition by country order by rating, id) rn
    from suppliers
) ranked
where rn <= 3
order by country;
```

Convert SQL to PySpark:
```sql
select *
from (
    select *, row_number() over (partition by brand order by price desc, id) as rn
    from products
    where array_contains(tags, 'new')
) as ranked
where rn <= 1;
```

Convert SQL to PySpark:
```sql
select *
from (
    select method, sum(case when method = 'cash' then 1 else 0 end) as cash_count, count(*) as row_count
    from payments
    group by method
) as sub
where row_count < 9;
```

Convert SQL to PySpark:
```sql
select id, device, started_at
from (
    select *, dense_rank() over (partition by device order by started_at desc) rn
    from sessions
) t
where rn = 1
order by 3 desc;
```

Convert SQL to PySpark:
```sql
select *
from (
    select *, row_number() over (partition by region order by opened_date desc, id) as rn
    from stores
    where store_name like '%Mall%'
) as r
where rn <= 2;
```

Convert SQL to PySpark:
```sql
select signup_quarter, signup_year, unique_segments
from (
    select quarter(signup_date) as signup_quarter, year(signup_date) as signup_year, count(distinct credit_limit) as unique_segments
    from customers
    group by quarter(signup_date), year(signup_date)
) as agg
where unique_segments >= 5;
```

Convert SQL to PySpark:
```sql
select hire_quarter, total_count
from (
    select quarter(hire_date) as hire_quarter, count(*) as total_count
    from employees
    group by quarter(hire_date)
) as t
where total_count < 6;
```

Convert SQL to PySpark:
```sql
select *
from (
    select *, row_number() over (partition by customer_id order by amount desc, id) rnk
    from orders
) ranked
where rnk <= 1
order by rnk desc;
```

Convert SQL to PySpark:
```sql
select account_id, refund_amount
from (
    select account_id, sum(case when txn_type = 'REFUND' then amount else 0 end) as refund_amount
    from transactions
    group by account_id
) as t
where refund_amount > 74;
```
